INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (1,'squat','徒手深蹲','下肢','力量','入门','无器械',8.0,'reps',15,NULL,'/gifs/squat.gif',ARRAY['双脚与肩同宽，脚尖微外八，双臂前平举','臀部向后下方坐，膝盖跟随脚尖方向下蹲','大腿接近与地面平行后匀速站起，回到起始位'],'膝盖不要内扣，下蹲时保持腰背自然挺直');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (2,'jack','开合跳','全身','有氧','入门','无器械',9.5,'duration',NULL,40,'/gifs/jack.gif',ARRAY['双脚并拢站直，双手贴于身体两侧','轻跳同时双腿分开、双手在头顶击掌','再跳回并拢姿态，保持前脚掌着地、匀速呼吸'],'用前脚掌缓冲落地，全程保持核心微收紧');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (3,'pushup','俯卧撑','上肢','力量','初级','无器械',8.5,'reps',10,NULL,'/gifs/pushup.gif',ARRAY['双手略宽于肩撑地，身体从头到脚成一条直线','弯曲手臂下降身体，胸部接近地面','匀速推起回到起始位，手肘约成 45 度夹角'],'力量不足可改为膝盖着地的跪姿俯卧撑');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (4,'plank','平板支撑','核心','稳定','入门','无器械',6.5,'duration',NULL,30,'/gifs/plank.gif',ARRAY['前臂与脚尖撑地，手肘在肩膀正下方','收紧腹部与臀部，身体保持一条直线','均匀呼吸，保持到目标时长'],'不要塌腰或撅臀，颈部自然延伸、眼看地面');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (5,'lunge','交替弓步蹲','下肢','力量','初级','无器械',8.0,'reps',12,NULL,'/gifs/lunge.gif',ARRAY['站直，一脚向前迈出一大步','前脚全掌踩实，弯曲双膝下沉至前腿约 90 度','蹬前脚站回，左右交替进行'],'前膝始终对准脚尖，不要超过脚尖太多');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (6,'crunch','仰卧卷腹','核心','力量','入门','无器械',6.0,'reps',15,NULL,'/gifs/crunch.gif',ARRAY['仰卧屈膝，双脚踩地，双手轻扶耳侧','腹部发力卷起上背部，下背部贴地','在顶峰稍停后缓慢下落，不要用手抱头拉扯'],'动作放慢，用腹肌而不是惯性完成');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (7,'knees','原地高抬腿','全身','有氧','初级','无器械',10.0,'duration',NULL,30,'/gifs/knees.gif',ARRAY['站直，双臂弯曲约 90 度','左右交替快速抬膝至腰部高度','手臂配合自然摆动，前脚掌着地'],'保持上身挺直，落地越轻越好');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (8,'stretch','站立伸展','拉伸','柔韧','入门','无器械',3.0,'duration',NULL,60,'/gifs/stretch.gif',ARRAY['双脚交叉站稳，双手交叠举过头顶','吸气向上延展，呼气向一侧轻微侧弯','保持呼吸，换侧重复，结束后抖动手脚放松'],'拉伸到有牵拉感即可，不要弹震、不要憋气');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (9,'bridge','仰卧臀桥','下肢','力量','入门','无器械',5.5,'reps',16,NULL,'/gifs/bridge.gif',ARRAY['仰卧屈膝，双脚靠近臀部踩地','臀部发力向上顶起，至肩髋膝成一条直线','顶峰夹紧臀部一秒，缓慢下落'],'发力重点在臀部，不要过度顶腰');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (10,'climber','登山跑','全身','有氧','中级','无器械',10.5,'duration',NULL,30,'/gifs/climber.gif',ARRAY['俯撑姿势，双手在肩下方、身体成直线','交替快速向胸前提膝，像原地跑步','保持髋部稳定不上下晃动'],'核心始终收紧，速度以动作不变形为前提');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (11,'wallsit','靠墙静蹲','下肢','稳定','初级','无器械',6.0,'duration',NULL,30,'/gifs/wallsit.gif',ARRAY['背靠墙站立，向前迈出双脚','沿墙下滑至大腿接近水平，小腿垂直地面','保持静蹲到目标时长，均匀呼吸'],'膝盖不超过脚尖，大腿酸了就结束');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (12,'tap','平板触肩','核心','稳定','中级','无器械',7.5,'reps',14,NULL,'/gifs/tap.gif',ARRAY['高位平板姿势，双手在肩下方撑地','保持躯干不晃，一手轻触对侧肩膀','左右交替进行，动作匀速'],'髋部尽量不左右摇摆，核心收紧');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (13,'calf','站姿提踵','下肢','力量','入门','无器械',4.5,'reps',20,NULL,'/gifs/calf.gif',ARRAY['站直，双脚与髋同宽，双手前平举或扶墙保持平衡','脚跟抬到最高，前脚掌撑地停一秒','控制速度缓慢落下，脚跟轻触地面后重复'],'下落越慢越好，充分感受小腿后侧发力');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (14,'twist','俄罗斯转体','核心','力量','初级','无器械',7.0,'reps',16,NULL,'/gifs/twist.gif',ARRAY['坐于地面，双膝弯曲脚跟着地，上身略向后倾','双手在胸前合十，背部挺直、腹部收紧','上身左右转动，双手随转体摆到髋部两侧'],'转体来自胸椎，不要只甩手臂，全程稳住下盘');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (15,'birdog','鸟狗式','核心','稳定','初级','无器械',6.0,'reps',12,NULL,'/gifs/birdog.gif',ARRAY['四点跪姿，双手在肩下、双膝在髋下','伸出对侧手和脚，直到与背部成一条直线','顶峰停一秒后收回，换另一侧进行'],'保持骨盆水平不翻胯，眼睛看向地面保护颈椎');
INSERT INTO exercises(id,slug,name,muscle_group,category,level,equipment,calories_per_min,measure,default_reps,default_seconds,gif_url,steps,tips) VALUES (16,'superman','小燕飞','核心','力量','初级','无器械',5.5,'reps',12,NULL,'/gifs/superman.gif',ARRAY['俯卧，双臂向前伸直、双腿向后伸直','背部发力，手臂和双腿同时轻轻抬离地面','顶峰停一秒，缓慢落下回到放松位'],'颈部保持放松不要仰头，抬起高度不必勉强');
